terable"]=1,["dsc"]=[[不大不小的骆驼房，地上散落着很多干草，不时有难闻的味道飘来。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[骆驼房(fb601_04)]],["canLeave"]=1,["id"]=[[fb601_04]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[兵库]],["permission"]=1,["enterable"]=1,["dsc"]=[[鸩羽山庄专门囤放兵器的仓库，门口有守卫把手，四周也布置了巡防。传闻里头的兵器足矣匹配给千军万马，攻城略池不在话下。]],["visible"]=1,["leftDown"]=[[fb601_09]],["dirIndex"]=0,["fullName"]=[[兵库(fb601_05)]],["canLeave"]=1,["id"]=[[fb601_05]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[大厅]],["permission"]=1,["enterable"]=1,["up"]=[[fb601_21]],["dsc"]=[[两张太师椅位于厅内中央，旁侧的雕花木桌上放有玉石摆设，墙面四角均挂有名家字画，雅致中可见奢华。]],["down"]=[[fb601_26]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[大厅(fb601_24)]],["canLeave"]=1,["id"]=[[fb601_24]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[四方小院]],["permission"]=1,["enterable"]=1,["up"]=[[fb601_23]],["dsc"]=[[四四方方的院落，右侧摆放着一张大理石桌，四个圆凳，另一边墙角的树枝上偶有毒蛇缠绕。]],["down"]=[[fb601_27]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[四方小院(fb601_25)]],["canLeave"]=1,["id"]=[[fb601_25]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb601_09]],["connectPoint"]=0,["name"]=[[鸩羽客栈]],["permission"]=1,["left"]=[[fb601_07]],["fullName"]=[[鸩羽客栈(fb601_08)]],["enterable"]=1,["up"]=[[fb601_03]],["dsc"]=[[鸩羽山山脚下的唯一一间客栈，上下三层，一应俱全。表面上供给往来商旅吃住，实则由鸩羽山庄主持，开设黑市，买卖江湖中的“棘手货”，不受官府管辖。]],["down"]=[[fb601_13]],["visible"]=1,["leftDown"]=[[fb601_12]],["dirIndex"]=0,["unit2"]=[[npc06b]],["unit1"]=[[npc06e]],["canLeave"]=1,["id"]=[[fb601_08]],["mapHide"]=0},{["operations"]={},["rightUp"]=[[fb601_05]],["right"]=[[fb601_10]],["connectPoint"]=0,["name"]=[[古河道]],["permission"]=1,["left"]=[[fb601_08]],["enterable"]=1,["stepMusic"]=[[jiaobu]],["dsc"]=[[已经干涸的古河道，龟裂的缝隙下偶能看到风化的鱼骨。]],["down"]=[[fb601_14]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[古河道(fb601_09)]],["canLeave"]=1,["id"]=[[fb601_09]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[虿盆]],["permission"]=1,["left"]=[[fb601_19]],["enterable"]=1,["dsc"]=[[鸩羽山为人所惧的地方，一层楼高的地下石坑上铸有特制的铁门，任凭武功再高，皆有进无出。坑内有蛇千条，为让人人饱受折磨，蛇毒均不致命。]],["fullName"]=[[虿盆(fb601_20)]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc09d]],["unit2"]=[[npc08d]],["unit1"]=[[npc05d]],["canLeave"]=1,["id"]=[[fb601_20]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[鸩羽山庄]],["permission"]=1,["fullName"]=[[鸩羽山庄(fb601_21)]],["enterable"]=1,["up"]=[[fb601_17]],["dsc"]=[[门口摆放着两座石狮，如江南府第。抬头时金漆匾额上刻着的“鸩羽山庄”四个字旁爬有一条毒蛇。门内春光似锦，门外可见山下戈壁沙漠，风光独特。]],["down"]=[[fb601_24]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc06g]],["unit1"]=[[npc06f]],["canLeave"]=1,["id"]=[[fb601_21]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb601_23]],["connectPoint"]=0,["name"]=[[竹影叶青斋]],["permission"]=1,["enterable"]=1,["up"]=[[fb601_19]],["dsc"]=[[深处竹林深处，屋舍皆由绿竹搭建，若不仔细，难以看出竹上攀爬的竹叶青。偶有风动，竹影摇曳间杀机暗伏。]],["fullName"]=[[竹影叶青斋(fb601_22)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc01]],["canLeave"]=1,["id"]=[[fb601_22]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[竹叶青蛇池]],["permission"]=1,["left"]=[[fb601_22]],["enterable"]=1,["dsc"]=[[绿竹搭建的小桥下开辟出一条细长的小池，池边小树上挂着的竹叶青远看如一道绿帘。]],["down"]=[[fb601_25]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[竹叶青蛇池(fb601_23)]],["canLeave"]=1,["id"]=[[fb601_23]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb601_29]],["connectPoint"]=0,["name"]=[[舟山蛇池]],["permission"]=1,["enterable"]=1,["dsc"]=[[绿竹搭建的小桥下开辟出一条细长的小池，池边的草地上不时窜出几条舟山毒蛇。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[舟山蛇池(fb601_28)]],["canLeave"]=1,["id"]=[[fb601_28]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb601_30]],["connectPoint"]=0,["name"]=[[舟山小筑]],["permission"]=1,["left"]=[[fb601_28]],["fullName"]=[[舟山小筑(fb601_29)]],["enterable"]=1,["dsc"]=[[临水而建，种有江南绿柳，上下两层倒映水中，远望如高楼。漆红凭栏上缠绕着的毒蛇，紧紧盯着悬挂在房檐上的几只鸟笼。]],["down"]=[[fb601_34]],["visible"]=1,["dirIndex"]=0,["un